UPDATE chapters
SET draft_outline = NULL,
    updated_time = NOW()
WHERE novel_id = #{novelId}
  AND volume_no = #{volumeNo}

UPDATE chapters
SET draft_outline = NULL,
    updated_time = NOW()
WHERE novel_id = #{novelId}
  AND chapter_no IN

    #{no}

UPDATE chapters
SET plan_contract = '{}'::jsonb,
    updated_time = NOW()
WHERE novel_id = #{novelId}
  AND volume_no = #{volumeNo}

UPDATE chapters
SET content = #{content},
    char_count = #{charCount},
    status = #{status},
    updated_time = NOW()
WHERE novel_id = #{novelId}
  AND chapter_no = #{chapterNo}
  AND plan_revision = #{planRevision}
  AND EXISTS (
      SELECT 1 FROM run r
      WHERE r.novel_id = #{novelId}
        AND r.active_plan_revision = #{planRevision}
  )

